// Package csvsum sums one column of a comma-separated stream.
package csvsum

import (
	"bufio"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// Sum adds up column (0-based) over every line of r.
func Sum(r io.Reader, column int) (float64, error) {
	sc := bufio.NewScanner(r)
	total := 0.0
	n := 0
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			continue
		}
		n++
		fields := strings.Split(line, ",")
		v, err := strconv.ParseFloat(fields[column], 64)
		if err != nil {
			return 0, fmt.Errorf("line %d: bad number %q", n, fields[column])
		}
		total += v
	}
	return total, sc.Err()
}

