package csvsum

import (
	"strings"
	"testing"
)

func TestSumOrdinary(t *testing.T) {
	got, err := Sum(strings.NewReader("1,2\n3,4\n5,6\n"), 1)
	if err != nil {
		t.Fatal(err)
	}
	if got != 12 {
		t.Fatalf("Sum = %v, want 12", got)
	}
}

