package acceptance_test

import (
	"strings"
	"testing"

	"example.com/csvsum"
)

func TestEmptyInput(t *testing.T) {
	got, err := csvsum.Sum(strings.NewReader(""), 0)
	if err != nil || got != 0 {
		t.Errorf("Sum(empty) = %v, %v; want 0, nil", got, err)
	}
	got, err = csvsum.Sum(strings.NewReader("\n  \n\t\n"), 0)
	if err != nil || got != 0 {
		t.Errorf("Sum(blank lines) = %v, %v; want 0, nil", got, err)
	}
}

func TestSpacesAroundFields(t *testing.T) {
	got, err := csvsum.Sum(strings.NewReader(" 1 , 2.5 \n3,4\n"), 1)
	if err != nil {
		t.Fatalf("Sum: %v", err)
	}
	if got != 6.5 {
		t.Errorf("Sum = %v, want 6.5", got)
	}
}

func TestBlankLinesCountTowardsLineNumbers(t *testing.T) {
	_, err := csvsum.Sum(strings.NewReader("1,2\n\n\nx,4\n"), 0)
	if err == nil {
		t.Fatal("a non-numeric field was accepted")
	}
	if !strings.Contains(err.Error(), "line 4") {
		t.Errorf("error = %q, want it to point at line 4", err)
	}
	if !strings.Contains(err.Error(), "bad number") {
		t.Errorf("error = %q, want it to say bad number", err)
	}
}

func TestShortRow(t *testing.T) {
	defer func() {
		if p := recover(); p != nil {
			t.Fatalf("Sum panicked on a short row: %v", p)
		}
	}()
	_, err := csvsum.Sum(strings.NewReader("1,2\n5\n"), 1)
	if err == nil {
		t.Fatal("a short row was accepted")
	}
	if !strings.Contains(err.Error(), "line 2: short row") {
		t.Errorf("error = %q, want \"line 2: short row\"", err)
	}
}

