// Package csvsum sums one column of a comma-separated stream.
package csvsum

import (
	"bufio"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// Sum adds up column (0-based) over every line of r. Blank lines are
// skipped but still counted, so the line numbers in an error are the
// positions a person reading the input would point at.
func Sum(r io.Reader, column int) (float64, error) {
	sc := bufio.NewScanner(r)
	total := 0.0
	line := 0
	for sc.Scan() {
		line++
		text := sc.Text()
		if strings.TrimSpace(text) == "" {
			continue
		}
		fields := strings.Split(text, ",")
		if column < 0 || column >= len(fields) {
			return 0, fmt.Errorf("line %d: short row", line)
		}
		field := strings.TrimSpace(fields[column])
		v, err := strconv.ParseFloat(field, 64)
		if err != nil {
			return 0, fmt.Errorf("line %d: bad number %q", line, field)
		}
		total += v
	}
	return total, sc.Err()
}
